import {mountSettings} from './settings.js';
import {mountFeishu,mountThreeAxes} from './feishu.js';
import {analyzeStructure} from './structure.js';
import {contractName} from './contract-name.js';
import {sectorFor} from './sectors.js';
import {mountResearch} from './research.js';
import {installLiveHome} from './live-home.js';
import {mountLiveMarket} from './live-market.js';
import {mountDataHub} from './data-hub.js';
import {VoiceController} from './voice.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let liveSnapshot=null,structure=null,reports=[],markets=[],selected=null,filter='all',period='D',view='home',tasks=[],decisions=[],configured=false,toastTimer;
const api=async(path,body)=>{const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(path==='/api/chat'?{...body,contextSymbol:selected?.symbol}:body)}:{});const j=await r.json();if(!r.ok)throw Error(j.error||'本地服务未响应');return j};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const sourceList=[['SHFE','上海期货交易所','日行情 / 仓单 / 合约规则','https://www.shfe.com.cn/reports/tradedata/datadownload/'],['INE','上海国际能源交易中心','日周数据 / 结算参数','https://www.ine.cn/reports/tradedata/dailyandweeklydata/'],['DCE','大连商品交易所','合约与市场数据','https://www.dce.com.cn/'],['CZCE','郑州商品交易所','市场数据与业务公告','https://www.czce.com.cn/'],['GFEX','广州期货交易所','行情与新品种规则','https://www.gfex.com.cn/']];
const number=v=>Number.isFinite(v)?v.toLocaleString('zh-CN',{maximumFractionDigits:3}):'未知';
function select(code){document.dispatchEvent(new CustomEvent('jarvis:select',{detail:code}));}
function planPreview(){const html=`<div class="plan-preview"><h3>${esc(selected?contractName(selected):'等待真实行情')}</h3><p>完成日K <b>${esc(structure?.asOf||'未知')}</b></p><p>结构测量 <b>${esc(structure?.day.state||'未知')}</b></p><p>交易计划 <b class="amber">尚未形成</b></p></div>`;$('#planPreview').innerHTML=html;$('#focusCard').innerHTML=html+'<button class="primary" data-action="evidence">查看真实证据 ↗</button>';$('#planCount').innerHTML='— <small>/ 待核验</small>';}
function updateEvidence(){structure=selected?analyzeStructure(selected):null;$('#evidenceName').textContent=selected?contractName(selected):'真实行情待连接';$('.evidence-title .tag').textContent='真实K线测量';$('#evidencePlot').textContent=structure?`完成日K：${structure.asOf||'不足'} · ${structure.cross}`:'暂无可核验行情';$('.evidence-lines').innerHTML=structure?`<p>月 / 周 / 日：${[structure.month,structure.week,structure.day].map(x=>esc(x.state)).join(' / ')}</p><p class="muted">产业证据需查询原始来源 · 阈值待校准</p>`:'<p>行情未就绪，不生成替代数据。</p>';const cycle=$('.cycle-body');if(cycle)cycle.innerHTML='<ul>'+['month','week','day'].map((key,i)=>`<li>${['月K','周K','日K'][i]} <span>${esc(structure?.[key].state||'未知')}</span></li>`).join('')+'</ul>';const note=$('.cycle-panel > small');if(note)note.textContent='完成K线测量 · 不等同于入场许可';$('.cycle-panel .tag').textContent='实际合约';planPreview();}
document.addEventListener('jarvis:quote',e=>{selected=e.detail.quote;liveSnapshot=e.detail.snapshot;markets=liveSnapshot.quotes||[];updateEvidence();});
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;$('#detailDialog').showModal()}
function evidence(){if(!structure){toast('真实行情尚未就绪');return}const x=structure;modal(`${contractName(selected)} · 真实证据`, `<span class="tag">${esc(x.source)}</span><h3>结构先过关，再谈机会</h3><p>报价时间 ${esc(selected.quoteTime)} · 采集状态 ${esc(liveSnapshot.status)} · 完成日K ${esc(x.asOf||'未知')}</p><div class="detail-grid"><div><span>最新价 / 昨收</span><b>${number(selected.last)} / ${number(selected.preClose)}</b></div><div><span>交易所收盘价</span><b>${number(selected.close)}</b></div></div><ul class="gate-list">${['month','week','day'].map((k,i)=>`<li>${['月','周','日'][i]}K <span>${esc(x[k].state)} · ${x[k].count} 根 · MA10 ${number(x[k].ma10)}</span></li>`).join('')}<li>完成日K穿越 <span>${esc(x.cross)}</span></li><li>近60日高 / 低 <span>${number(x.range?.high)} / ${number(x.range?.low)}</span></li><li>账户风险 <span>未连接，未知</span></li></ul><h3>3—8日区间实测</h3><p>这是区间测量，尚未判定为合格平台。</p>${x.platforms.map(r=>`<p>${r.days}日：${number(r.low)}—${number(r.high)} · 宽度/末根收盘 ${number(r.widthPct)}%</p>`).join('')}<p>${esc(x.notice)}</p><h3>反证与产业验证</h3><p>价格结构不能替代库存、基差、供需与事件证据。点击研究后查询原始来源，并保留来源时间与缺口。</p><button class="primary" data-action="analyze">研究 ${esc(contractName(selected))} ↗</button>`)}
function reviewPlan(){navigate('metal')}
const titles={fire:['FIRE / OPPORTUNITY RADAR','火 · 机会雷达'],water:['WATER / EVIDENCE RESEARCH','水 · 深度研究'],metal:['METAL / DECISION CENTER','金 · 决策中心'],earth:['EARTH / EXECUTION TRACKING','土 · 执行跟踪'],wood:['WOOD / SYSTEM REVIEW','木 · 复盘迭代'],sources:['DATA / CONNECTIONS','数据与连接'],settings:['SETTINGS / AGENT & CHANNELS','设置 · Agent 与消息通道']};
function navigate(v){view=v;$('#dashboard').hidden=v!=='home';$('#workspace').hidden=v==='home';$$('.sidebar [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v!=='home')renderWorkspace();window.scrollTo({top:0,behavior:'smooth'})}
function taskCards(){return reports.length?reports.map(t=>`<div class="work-item"><div><b>${esc(t.name)}</b><p>${esc(t.stage||t.status)}</p><small>${esc(t.created)}</small></div><button class="quiet" data-report="${esc(t.id)}">查看报告 ↗</button></div>`).join(''):'<div class="no-data">尚无真实研究记录。</div>'}
function renderWorkspace(){const [ey,t]=titles[view];$('#workEyebrow').textContent=ey;$('#workTitle').textContent=t;let html='';
if(view==='fire')html=`<div class="work-banner">真实主力合约研究池：成交量与持仓量均大于1万手。结构测量不是机会评级；行情时间以各合约为准。</div><table class="work-table"><thead><tr><th>品种</th><th>板块</th><th>完成日K / MA10</th><th>操作</th></tr></thead><tbody>${markets.map(q=>{const a=analyzeStructure(q);return `<tr><td>${esc(contractName(q))}</td><td>${esc(sectorFor(q))}</td><td>${esc(a.day.state)} · ${number(a.day.ma10)}</td><td><button class="quiet" data-research="${esc(q.symbol)}">研究 ↗</button></td></tr>`}).join('')}</tbody></table>`;
if(view==='metal')html='<div class="work-banner">尚无完成全部规则核验的交易计划。真实研究报告可供人工复核，不会自动转换为交易指令。</div><div class="work-list">'+taskCards()+'</div>';
if(view==='earth')html='<div class="work-banner">期货公司及接口权限待确认。账户权益、持仓、委托与成交均未知。</div><h3>真实后台研究</h3><div class="work-list">'+taskCards()+'</div>';
if(view==='wood')html='<div class="work-banner">打开报告可保存“得到支持、出现反证、已失效”等复核记录，下一次同品种研究会读取。未接入真实成交，不计算交易胜率或后验概率。</div><div class="work-list">'+taskCards()+'</div>';
if(view==='sources')html=`<div class="work-banner">TqSdk 国内期货行情 · DeepSeek 研究 · 官方来源检索。当前不包含 A 股或期货账户。</div><div class="work-card"><h3>语音</h3><p>现有浏览器识别与播报不是全双工。GPT-Live 全双工接口已准备，需配置 OpenAI API Key 后进行麦克风实测。</p><button data-action="call">打开对话</button></div>`;
$('#workspaceBody').innerHTML=html;if(view==='settings')mountSettings();if(view==='water')mountResearch(selected?.symbol||'');if(view==='fire')mountThreeAxes();if(view==='sources'){mountDataHub();mountLiveMarket();mountFeishu();}}
async function refresh(){try{let s=await api('/api/status');configured=s.chatConfigured??s.llm?.configured??false;reports=await api('/api/research/reports');tasks=reports;decisions=[];$('#health').textContent=s.marketConnected?'本地服务在线 · TqSdk采集在线':'本地服务在线 · 行情状态 '+s.marketStatus;const marketHealth=document.querySelector('#marketHealth');if(marketHealth)marketHealth.textContent=s.marketConnected?'采集在线':s.marketStatus;$('#runningCount').textContent=tasks.filter(t=>t.status==='running').length;planPreview();return s}catch{ $('#health').textContent='本地服务离线';throw Error('本地服务未连接，请通过启动脚本打开页面')}}
async function runTask(kind='scan'){if(kind==='scan'){navigate('fire');return '已打开真实行情研究池'}if(kind==='review'){await refresh();navigate('wood');return '已打开真实研究复核记录'}if(!selected){toast('请先等待真实行情并选择品种');return}navigate('water');return '已选择'+contractName(selected)+'，点击开始深入研究可启动后台任务。'}
async function command(){return '请使用已配置的 DeepSeek 查询真实行情与研究。'}
const voice=new VoiceController({api,command,onTool:async()=>{await refresh();if(view!=='home')renderWorkspace()},toast,isConfigured:()=>configured});
function settings(){navigate('settings')}
function focusToggle(value){const v=value??!document.body.classList.contains('focus');document.body.classList.toggle('focus',v);$('#focusMode').textContent=v?'◎ 全息模式':'◎ 专注模式';localStorage.setItem('jarvis-focus',String(v))}
$('#focusMode').onclick=()=>focusToggle();$('#settings').onclick=settings;$('#closeDialog').onclick=()=>$('#detailDialog').close();$('#detailDialog').addEventListener('click',e=>{if(e.target===$('#detailDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#reviewPlan').onclick=reviewPlan;$('#chartDetails').onclick=evidence;$('#viewEvidence').onclick=evidence;$('#callOrb').onclick=()=>voice.open();$('#textChat').onclick=()=>voice.open();$('#navCall').onclick=()=>voice.open();
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.research){select(b.dataset.research);navigate('water')}if(b.dataset.report){localStorage.setItem('jarvis-research-job',b.dataset.report);navigate('water')}if(b.dataset.action){const a=b.dataset.action;if(a==='scan')runTask('scan');if(a==='analyze'){$('#detailDialog').close();runTask('analysis')}if(a==='audit')runTask('review');if(a==='plan')reviewPlan();if(a==='evidence')evidence();if(a==='call')voice.open()}});
document.addEventListener('change',e=>{if(e.target.id==='reduceMotion'){document.body.classList.toggle('reduced',e.target.checked);localStorage.setItem('jarvis-motion',String(e.target.checked))}if(e.target.id==='focusSetting')focusToggle(e.target.checked)});
function tick(){let now=new Date();$('#clock').textContent=now.toLocaleTimeString('en-GB',{timeZone:'Asia/Shanghai'});$('#date').textContent=now.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'}).replaceAll('-','.')+'  '+now.toLocaleDateString('en-US',{weekday:'short',timeZone:'Asia/Shanghai'}).toUpperCase()};tick();setInterval(tick,1000);
updateEvidence();focusToggle(localStorage.getItem('jarvis-focus')==='true');document.body.classList.toggle('reduced',localStorage.getItem('jarvis-motion')==='true');
try{await refresh();}catch(e){toast(e.message);$('#marketRows').innerHTML='<div class="no-data">本地服务未连接，请使用启动脚本打开。</div>'}
window.addEventListener('beforeunload',()=>voice.stop());

installLiveHome();
setInterval(()=>refresh().catch(()=>{}),10000);
